def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) == 0:
        raise Blocked("no community available")
    return statusCode == 200 and responseBody.get("code") == 0 and all(item.get("id") and item.get("name") for item in data) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data") or {}
    return statusCode == 200 and responseBody.get("code") == 0 and bool(data.get("accessToken")) and bool(data.get("refreshToken")) and bool((data.get("user") or {}).get("id")) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data") or {}
    return statusCode == 200 and responseBody.get("code") == 0 and bool(data.get("id")) and data.get("publisherId") == globalParam.get("a_id") and data.get("communityId") == globalParam.get("c1") and data.get("status") == "open" and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    msg = responseBody.get("message") or ""
    return 400 <= statusCode < 500 and responseBody.get("code") != 0 and "Exception" not in msg and "SQL" not in msg and "Traceback" not in msg

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data") or {}
    items = data.get("items")
    if not isinstance(items, list):
        return False
    return statusCode == 200 and responseBody.get("code") == 0 and all(room.get("topicId") != globalParam.get("t") for room in items) and bool(responseBody.get("requestId"))
